package com.example.domain.model.i18n

internal object DuaHa1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Idan an farka daga barci", "Godiya ta tabbata ga Allah wanda Ya rayar da mu bayan Ya kashe mu (mu yi barci), kuma zuwa gare Shi ne dawowa.", "Ana karantawa nan take bayan an farka a matsayin godiya ga Allah.", "Annabi ﷺ yana karanta wannan idan ya farka — fara rana da godiya da tunawa da lahira."),
        "dua_leaving_home" to DuaText("Idan za a fita gida", "Da sunan Allah, na dogara ga Allah, babu wani karfi ko iko sai na Allah.", "Ana karantawa idan za a fita gida don neman kariya.", "Ana ce wa wanda ya karanta wannan: an shiryar da kai, an isar maka, an kuma kare ka — shaidan kuma zai nisance shi."),
        "dua_anxiety_distress" to DuaText("Addu'ar damuwa da bakin ciki", "Ya Allah, ina neman tsari a gare Ka daga damuwa da bakin ciki, daga rashin karfi da ragwanci, daga rowa da tsoro, daga nauyin bashi da zaluncin mutane.", "A lokacin damuwa, bakin ciki, bashi, da wahalar zuciya.", "Annabi ﷺ yakan karanta wannan addu'a sau da yawa domin neman tsari daga bakin ciki, ragwanci, da bashi."),
        "dua_sayyidul_istighfar" to DuaText("Shugaban neman gafara (Sayyidul Istighfar)", "Ya Allah, Kai ne Ubangijina, babu abin bautawa da gaskiya sai Kai. Ka halicce ni kuma ni bawanka ne. Ina kan alkawarinka da yarjejeniyarka gwargwadon ikona. Ina neman tsari a gare Ka daga sharrin abin da na aikata. Na yarda da ni'imarka a kaina kuma na yarda da zunubina, don haka Ka gafarta mini, domin babu mai gafarta zunubai sai Kai.", "Ana karantawa safe da yamma — mafi kyawun addu'ar tuba wanda Annabi ﷺ ya koyar.", "Wanda ya karanta wannan da yamma da cikakken imani ya kuma mutu a wannan dare zai shiga Aljanna; haka ma wanda ya karanta shi da safe."),
        "dua_parents" to DuaText("Addu'a domin iyaye", "Ya Ubangijina, Ka yi musu rahama kamar yadda suka rene ni tun ina karami.", "Addu'a daga Alkur'ani a matsayin sakayya ga kulawar iyaye tun yarinta.", "Allah Ya umarci wannan addu'a domin iyaye kai tsaye a cikin Alkur'ani."),
        "dua_entering_mosque" to DuaText("Idan za a shiga masallaci", "Ya Allah, Ka bude mini kofofin rahamarka.", "Ana karantawa idan za a shiga masallaci da kafar dama.", "Annabi ﷺ ya koyar da wannan addu'a domin shiga masallaci."),
        "dua_morning_asbahna" to DuaText("Ambaton safe", "Mun kai safiya kuma mulki na Allah ne; godiya ta tabbata ga Allah; babu abin bautawa da gaskiya sai Allah shi kadai, ba shi da abokin tarayya; mulki na Shi ne, godiya kuma ta Shi ce, kuma Shi Mai iko ne a kan komai.", "Ambaton da aka shar'anta a karanta da safe.", "Fara rana ta hanyar yarda da mulkin Allah da hadin kansa."),
        "dua_evening_amsayna" to DuaText("Ambaton yamma", "Mun kai yamma kuma mulki na Allah ne; godiya ta tabbata ga Allah; babu abin bautawa da gaskiya sai Allah shi kadai, ba shi da abokin tarayya; mulki na Shi ne, godiya kuma ta Shi ce, kuma Shi Mai iko ne a kan komai.", "Ambaton da aka shar'anta a karanta da yamma.", "Fara dare ta hanyar yarda da mulkin Allah da hadin kansa."),
        "dua_before_sleep" to DuaText("Kafin barci", "Da sunanka ya Allah nake mutuwa kuma nake rayuwa.", "Ana karantawa bayan an kwanta don barci.", "Annabi ﷺ yana karanta wannan kafin barci."),
        "dua_travel" to DuaText("Addu'ar tafiya", "Tsarki ya tabbata ga wanda Ya hore mana wannan, alhali ba mu iya iko da shi ba; kuma lalle mu zuwa ga Ubangijinmu za mu koma.", "Ana karantawa idan an hau abin hawa bayan an yi kabbara sau uku.", "Addu'ar tafiya da aka shar'anta domin kariya da albarka."),
        "dua_ayatul_kursi" to DuaText("Ayatul Kursiyu bayan sallah", "Allah, babu abin bautawa da gaskiya sai Shi, Rayayye, Mai tsayawa da kome. Bacci ba ya kama Shi, barci ma ba ya kama Shi. Na Shi ne abin da yake a sammai da abin da yake a kasa. Wanene zai iya yin ceto a wurinsa sai da izininsa? Ya san abin da yake gaban su da abin da yake bayan su. Ba su iya kewaye da kome daga ilminsa sai abin da Ya so. Kursiyinsa ya kewaye sammai da kasa, kuma tsare su ba ya nauyaya masa. Shi ne Madaukaki, Mai girma.", "Ana karantawa bayan kowace sallar farilla da kafin barci.", "Wanda ya karanta wannan bayan kowace sallar farilla, babu abin da zai hana shi shiga Aljanna sai mutuwa; wanda ya karanta kafin barci za a kare shi har safe."),
        "dua_hasbunallah" to DuaText("Allah Ya isar mana", "Allah Ya isar mana, Shi ne Mafi kyawun wakili.", "Ana karantawa idan ana jin tsoron makiyi ko babbar hadari.", "Annabi Ibrahim ya fadi haka lokacin da aka jefa shi cikin wuta, Annabi ﷺ kuma ya fadi haka a lokacin hadari."),
        "dua_entering_home" to DuaText("Idan za a shiga gida", "Da sunan Allah muka shiga, da sunan Allah muka fita, kuma ga Ubangijinmu Allah muka dogara.", "Ana karantawa idan za a shiga gida tare da ambaton sunan Allah da gaisuwa.", "Ga wanda ya ambaci Allah idan zai shiga gida da kuma cin abinci, shaidan zai ce: babu wurin kwana ko abincin dare a gare ku."),
        "dua_yunus" to DuaText("Addu'ar Annabi Yunusa (tsira ta tabbata a gare shi)", "Babu abin bautawa da gaskiya sai Kai, tsarki ya tabbata a gare Ka; lalle ni na kasance daga azzalumai.", "Addu'ar Annabi Yunusa a cikin cikin kifi — domin kowace wahala.", "Babu musulmi da zai roka da wannan a kowane al'amari face Allah Ya amsa masa."),
        "dua_karb" to DuaText("Addu'ar matsanancin wahala", "Babu abin bautawa da gaskiya sai Allah, Mai girma, Mai hakuri. Babu abin bautawa da gaskiya sai Allah, Ubangijin Al'arshi mai girma. Babu abin bautawa da gaskiya sai Allah, Ubangijin sammai da kasa da Al'arshi mai daraja.", "Ana karantawa a lokacin matsanancin wahala da kunci.", "Annabi ﷺ yana karanta wannan a lokacin wahala."),
    )
}
